files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2d3142;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  background: #3a3f55;
  border-radius: 16px;
  padding: 32px 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  max-width: 600px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  color: #f0f0f0;
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.5px;
}

.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
}

.swatch {
  flex: 1 1 80px;
  min-width: 80px;
  max-width: 120px;
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  transition: transform 0.15s ease;
}

.swatch:focus-within {
  outline: 3px solid #f9c74f;
  outline-offset: 2px;
}

.color-box {
  height: 100px;
  width: 100%;
  transition: background-color 0.2s ease;
}

.swatch-footer {
  background: #2d3142;
  padding: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.hex-code {
  color: #f0f0f0;
  font-size: 0.85rem;
  font-weight: 500;
  font-family: 'Courier New', monospace;
  text-transform: uppercase;
}

.lock-btn {
  background: none;
  border: 2px solid #5a5f7a;
  border-radius: 6px;
  color: #a0a5c0;
  cursor: pointer;
  font-size: 1rem;
  line-height: 1;
  padding: 4px 6px;
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  min-height: 32px;
}

.lock-btn:hover {
  border-color: #f9c74f;
  color: #f9c74f;
  background: rgba(249, 199, 79, 0.1);
}

.lock-btn:focus-visible {
  outline: 3px solid #f9c74f;
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.92);
}

.lock-btn.locked {
  border-color: #f9c74f;
  color: #f9c74f;
  background: rgba(249, 199, 79, 0.15);
}

.generate-btn {
  background: #f9c74f;
  border: none;
  border-radius: 10px;
  color: #2d3142;
  cursor: pointer;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 14px 24px;
  transition: all 0.15s ease;
  letter-spacing: 0.5px;
  align-self: center;
  min-width: 160px;
}

.generate-btn:hover {
  background: #fbd46d;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(249, 199, 79, 0.3);
}

.generate-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

.generate-btn:active {
  transform: translateY(0) scale(0.98);
  background: #e8b83e;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .swatch {
    flex: 1 1 60px;
    min-width: 60px;
  }
  .color-box {
    height: 80px;
  }
  .hex-code {
    font-size: 0.75rem;
  }
}

(function () {
  'use strict';

  var SWATCH_COUNT = 5;
  var swatches = [];
  var locks = [];

  var container = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    function f(n) {
      var k = (n + h / 30) % 12;
      var color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    }
    return '#' + f(0) + f(8) + f(4);
  }

  function generatePalette() {
    var baseHue = Math.random() * 360;
    var scheme = [0, 30, 120, 180, 240];
    var sat = 60 + Math.random() * 25;
    var light = 45 + Math.random() * 15;
    var colors = [];
    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (locks[i] && swatches[i]) {
        colors.push(swatches[i].hex);
      } else {
        var hue = (baseHue + scheme[i] + (Math.random() * 15 - 7.5)) % 360;
        var s = Math.min(100, Math.max(30, sat + (Math.random() * 20 - 10)));
        var l = Math.min(80, Math.max(30, light + (Math.random() * 15 - 7.5)));
        colors.push(hslToHex(hue, s, l));
      }
    }
    return colors;
  }

  function render() {
    container.innerHTML = '';
    swatches = [];
    for (var i = 0; i < SWATCH_COUNT; i++) {
      var swatch = document.createElement('div');
      swatch.className = 'swatch';
      swatch.setAttribute('role', 'listitem');

      var colorBox = document.createElement('div');
      colorBox.className = 'color-box';

      var footer = document.createElement('div');
      footer.className = 'swatch-footer';

      var hexSpan = document.createElement('span');
      hexSpan.className = 'hex-code';

      var lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-label', 'Lock color ' + (i + 1));
      lockBtn.setAttribute('aria-pressed', 'false');
      lockBtn.textContent = '\uD83D\uDD13';

      (function (index, btn) {
        btn.addEventListener('click', function () {
          locks[index] = !locks[index];
          btn.classList.toggle('locked', locks[index]);
          btn.setAttribute('aria-pressed', String(locks[index]));
          btn.setAttribute('aria-label', (locks[index] ? 'Unlock' : 'Lock') + ' color ' + (index + 1));
          btn.textContent = locks[index] ? '\uD83D\uDD12' : '\uD83D\uDD13';
        });
      })(i, lockBtn);

      footer.appendChild(hexSpan);
      footer.appendChild(lockBtn);
      swatch.appendChild(colorBox);
      swatch.appendChild(footer);
      container.appendChild(swatch);

      swatches.push({ el: swatch, box: colorBox, hexEl: hexSpan, hex: '#000000' });
    }
    applyColors(generatePalette());
  }

  function applyColors(colors) {
    for (var i = 0; i < SWATCH_COUNT; i++) {
      swatches[i].hex = colors[i];
      swatches[i].box.style.backgroundColor = colors[i];
      swatches[i].hexEl.textContent = colors[i];
    }
  }

  generateBtn.addEventListener('click', function () {
    applyColors(generatePalette());
  });

  render();
})();
